UBaseType_t ux_Task_Get_ਸੰਖਿਆ_ਦਾ_Tasks( ਖਾਲੀ )
{
    trace_ENTER_ux_Task_Get_ਸੰਖਿਆ_ਦਾ_Tasks();

    /* A critical section is not required because the variables are of type
     * BaseType_t. */
    trace_RETURN_ux_Task_Get_ਸੰਖਿਆ_ਦਾ_Tasks( ux_Current_ਸੰਖਿਆ_ਦਾ_Tasks );

    ਵਾਪਸ ux_Current_ਸੰਖਿਆ_ਦਾ_Tasks;
}
